/**
 * Минуты от полуночи до конца дня (включительно) — закрытый интервал [start, end].
 * start > end — окно пересекает полночь (например, 16:30-00:30).
 * Пустая строка — окно отключено. Формат: "HH:MM-HH:MMZ" (UTC).
 * Целые сутки — «00:00-23:59».
 *
 * @param mixed $value
 *
 * @throws \InvalidArgumentException строка некорректна
 */
public static function parse(mixed $value): self
{
    if ($value === null || (is_string($value) && trim($value) === '')) {
        return new self(-1, -1);
    }

    Input::asNonEmptyString($value, 'off_peak');

    if (!is_string($value) || !preg_match(
        '/^(\d{2}):(\d{2})-(\d{2}):(\d{2})Z$/',
        trim($value),
        $m,
    ) === 1) {
        throw new \InvalidArgumentException(
            'off_peak: ожидается строка "HH:MM-HH:MMZ" (UTC), например "16:30-00:30Z" или "00:00-23:59"',
        );
    }

    $start = (int) $m[1] * 60 + (int) $m[2];
    $end = (int) $m[3] * 60 + (int) $m[4];

    if ((int) $m[1] > 23 || (int) $m[3] > 23 || (int) $m[2] > 59 || (int) $m[4] > 59) {
        throw new \InvalidArgumentException('off_peak: время вне диапазона 00:00-23:59');
    }

    return new self($start, $end);
}

public function isEmpty(): bool
{
    return $this->startMinutes < 0;
}

/**
 * Закрытый интервал: обе границы включены. start > end — пересечение полуночи.
 */
public function covers(int $minutesFromMidnight): bool
{
    if ($this->isEmpty() || $minutesFromMidnight < 0 || $minutesFromMidnight > 1439) {
        return false;
    }

    if ($this->startMinutes <= $this->endMinutes) {
        return $minutesFromMidnight >= $this->startMinutes
            && $minutesFromMidnight <= $this->endMinutes;
    }

    return $minutesFromMidnight >= $this->startMinutes
        || $minutesFromMidnight <= $this->endMinutes;
}

